#include <bits/stdc++.h>
using namespace std;

#define F first
#define S second
#define pb push_back
#define lb lower_bound
#define ub upper_bound
#define pii pair<int, int>
#define all(x) x.begin(), x.end()
#define fix fixed << setprecision(10)
#define rep(i, a, b) for (int i = int(a); i <= int(b); i++)
#define repb(i, b, a) for (int i = int(b); i >= int(a); i--)
#define FastIO ios_base::sync_with_stdio(false), cin.tie(nullptr), cout.tie(nullptr)

typedef double db;
typedef long long ll;

const int N = 5e5 + 5;
const int mod = 998244353;

ll n, k, f[N], inv[N];

void pre() {
    f[0] = 1;
    rep(i, 1, 5e5) f[i] = f[i - 1] * i % mod;
    inv[int(5e5)] = 235551727;
    repb(i, 5e5 - 1, 0) inv[i] = (i + 1LL) * inv[i + 1] % mod;
}

signed main() {
    FastIO;
    pre();

    cin >> n >> k;

    ll ans = 0;
    rep(i, 1, n) {
        if (n / i >= k) {
            ans = (ans + f[n / i - 1] * inv[k - 1] % mod * inv[n / i - k]) % mod;
        }
    }

    cout << ans;
    return 0;
}

